    "webFile": "/**\n * Nothing UI — Input & Textarea (copy-in template via `npx nthgui add input`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface InputWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function InputContainer({ className, children, ...props }: InputWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"input\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import { ActivityIndicator, TextInput, View } from \"react-native\";\nimport { createNativeTheme } from \"nthgui/native\";\n\nexport function Input({\n  value,\n  onChangeText,\n  placeholder,\n  loading = false,\n}: {\n  value: string;\n  onChangeText: (v: string) => void;\n  placeholder?: string;\n  loading?: boolean;\n}) {\n  const theme = createNativeTheme(\"dark\");\n  return (\n    <View\n      accessibilityState={{ busy: loading }}\n      style={{\n        height: 44,\n        flexDirection: \"row\",\n        alignItems: \"center\",\n        borderRadius: 8,\n        borderWidth: 1,\n        borderColor: theme.colors.borderStrong,\n        backgroundColor: theme.colors.surface,\n        paddingHorizontal: 12,\n        gap: 8,\n      }}\n    >\n      <TextInput\n        value={value}\n        editable={!loading}\n        onChangeText={onChangeText}\n        placeholder={placeholder}\n        placeholderTextColor={theme.colors.foregroundMuted}\n        style={{ flex: 1, color: theme.colors.foreground, fontFamily: \"JetBrainsMono-Regular\" }}\n      />\n      {loading && <ActivityIndicator size=\"small\" color={theme.colors.foregroundMuted} />}\n    </View>\n  );\n}",
