    "webFile": "/**\n * Nothing UI — Segmented & Toggle Group (copy-in template via `npx nthgui add segmented-control`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface SegmentedControlWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function SegmentedControlContainer({ className, children, ...props }: SegmentedControlWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"segmented-control\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
