    "webFile": "/**\n * Nothing UI — Skeleton, Dot Loader & Empty (copy-in template via `npx nthgui add skeleton`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface SkeletonWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function SkeletonContainer({ className, children, ...props }: SkeletonWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"skeleton\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import { ActivityIndicator, Text, View } from \"react-native\";\nimport { createNativeTheme, type NativeLoaderVariant } from \"nthgui/native\";\n\nexport function Loader({\n  variant = \"normal\",\n  label = \"Loading\",\n}: {\n  variant?: NativeLoaderVariant;\n  label?: string;\n}) {\n  const theme = createNativeTheme(\"dark\");\n  return (\n    <View accessibilityRole=\"progressbar\" accessibilityLabel={label} accessibilityState={{ busy: true }}>\n      {variant === \"normal\" ? (\n        <ActivityIndicator size=\"small\" color={theme.colors.foreground} />\n      ) : (\n        <Text style={{ fontFamily: \"JetBrainsMono-Regular\", fontSize: 12, color: theme.colors.foreground }}>\n          {variant === \"dots\" ? \"•••\" : variant === \"bars\" ? \"|||\" : \"◯\"}\n        </Text>\n      )}\n    </View>\n  );\n}\n\nexport function Skeleton({ width = \"100%\", height = 16, radius = 8 }: { width?: number | string; height?: number; radius?: number }) {\n  const theme = createNativeTheme(\"dark\");\n  return <View style={{ width: width as any, height, borderRadius: radius, backgroundColor: theme.colors.surfaceRaised }} />;\n}",
