    "webFile": "/**\n * Nothing UI — Logo (Brand) (copy-in template via `npx nthgui add brand-logo`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface BrandLogoWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function BrandLogoContainer({ className, children, ...props }: BrandLogoWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"brand-logo\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import { View, Text, StyleSheet } from \"react-native\";\nimport Svg, { Circle } from \"react-native-svg\";\nimport { createNativeTheme } from \"nthgui/native\";\n\nexport function BrandLogo({ showWordmark = true }: { showWordmark?: boolean }) {\n  const theme = createNativeTheme(\"dark\");\n  return (\n    <View style={styles.row}>\n      <Svg width={24} height={24} viewBox=\"0 0 24 24\">\n        {[4, 12, 20].flatMap((cy, r) =>\n          [4, 12, 20].map((cx, c) => (\n            <Circle key={`${r}-${c}`} cx={cx} cy={cy} r={2.2} fill={r === 0 && c === 2 ? theme.colors.signal : theme.colors.foreground} />\n          )),\n        )}\n      </Svg>\n      {showWordmark && <Text style={[styles.word, { color: theme.colors.foreground }]}>NOTHING UI</Text>}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  row: { flexDirection: \"row\", alignItems: \"center\", gap: 10 },\n  word: { fontFamily: \"Doto-Regular\", fontSize: 18, letterSpacing: 1.4 },\n});",
