    "webFile": "/**\n * Nothing UI — Motion (Fade, Slide, Scale, Stagger) (copy-in template via `npx nthgui add motion-kit`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface MotionKitWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function MotionKitContainer({ className, children, ...props }: MotionKitWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"motion-kit\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import * as React from \"react\";\nimport { Animated, AccessibilityInfo } from \"react-native\";\n\nexport function MotionReveal({ children, delay = 0 }: { children: React.ReactNode; delay?: number }) {\n  const opacity = React.useRef(new Animated.Value(0)).current;\n  const translateY = React.useRef(new Animated.Value(10)).current;\n\n  React.useEffect(() => {\n    AccessibilityInfo.isReduceMotionEnabled().then((reduced) => {\n      if (reduced) {\n        opacity.setValue(1);\n        translateY.setValue(0);\n        return;\n      }\n      Animated.parallel([\n        Animated.timing(opacity, { toValue: 1, duration: 240, delay, useNativeDriver: true }),\n        Animated.timing(translateY, { toValue: 0, duration: 240, delay, useNativeDriver: true }),\n      ]).start();\n    });\n  }, [delay, opacity, translateY]);\n\n  return <Animated.View style={{ opacity, transform: [{ translateY }] }}>{children}</Animated.View>;\n}",
