    "webFile": "/**\n * Nothing UI — Hardware KPI Grid (copy-in template via `npx nthgui add metric-grid`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface MetricGridWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function MetricGridContainer({ className, children, ...props }: MetricGridWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"metric-grid\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import { View, Text, StyleSheet } from \"react-native\";\nimport { createNativeTheme } from \"nthgui/native\";\n\nexport function MetricGrid({ items }: { items: { label: string; value: string }[] }) {\n  const theme = createNativeTheme(\"dark\");\n  return (\n    <View style={styles.grid}>\n      {items.map((item) => (\n        <View key={item.label} style={[styles.tile, { borderColor: theme.colors.border, backgroundColor: theme.colors.surface }]}>\n          <Text style={[styles.lbl, { color: theme.colors.foregroundMuted }]}>{item.label}</Text>\n          <Text style={[styles.val, { color: theme.colors.foreground }]}>{item.value}</Text>\n        </View>\n      ))}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  grid: { flexDirection: \"row\", flexWrap: \"wrap\", gap: 10 },\n  tile: { width: \"47%\", borderWidth: 1, borderRadius: 16, padding: 14, gap: 4 },\n  lbl: { fontFamily: \"JetBrainsMono-Regular\", fontSize: 10, letterSpacing: 1 },\n  val: { fontFamily: \"Doto-Regular\", fontSize: 26, fontVariant: [\"tabular-nums\"] },\n});",
