    "description": "Multi-column reorderable hardware task board supporting both drag-and-drop and accessible up/down + column-shift keyboard controls.",
    "webFile": "/**\n * Nothing UI — Sortable Board (copy-in template via `npx nthgui add sortable-board`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface SortableBoardWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function SortableBoardContainer({ className, children, ...props }: SortableBoardWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"sortable-board\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import * as React from \"react\";\nimport { View, Pressable, Text, LayoutAnimation, StyleSheet } from \"react-native\";\nimport { createNativeTheme } from \"nthgui/native\";\n\nexport function SortableBoard({ initial }: { initial: string[] }) {\n  const theme = createNativeTheme(\"dark\");\n  const [items, setItems] = React.useState(initial);\n\n  const move = (idx: number, dir: -1 | 1) => {\n    const nextIdx = idx + dir;\n    if (nextIdx < 0 || nextIdx >= items.length) return;\n    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);\n    const next = [...items];\n    [next[idx], next[nextIdx]] = [next[nextIdx], next[idx]];\n    setItems(next);\n  };\n\n  return (\n    <View style={styles.list}>\n      {items.map((item, idx) => (\n        <View key={item} style={[styles.row, { borderColor: theme.colors.border, backgroundColor: theme.colors.surface }]}>\n          <Text style={[styles.lbl, { color: theme.colors.foreground }]}>{item}</Text>\n          <View style={styles.ctrls}>\n            <Pressable onPress={() => move(idx, -1)} style={styles.btn}><Text style={{ color: theme.colors.foreground }}>↑</Text></Pressable>\n            <Pressable onPress={() => move(idx, 1)} style={styles.btn}><Text style={{ color: theme.colors.foreground }}>↓</Text></Pressable>\n          </View>\n        </View>\n      ))}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  list: { gap: 8 },\n  row: { borderWidth: 1, borderRadius: 12, paddingHorizontal: 14, minHeight: 48, flexDirection: \"row\", alignItems: \"center\", justifyContent: \"space-between\" },\n  lbl: { fontFamily: \"JetBrainsMono-Regular\", fontSize: 13 },\n  ctrls: { flexDirection: \"row\", gap: 6 },\n  btn: { width: 36, height: 36, alignItems: \"center\", justifyContent: \"center\" },\n});",
