    "description": "Collapsible categorized navigation sidebar with live filter input, platform toggle, active-item indicator, and compact rail collapse mode.",
    "webFile": "/**\n * Nothing UI — Documentation Sidebar (copy-in template via `npx nthgui add sidebar`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface SidebarWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function SidebarContainer({ className, children, ...props }: SidebarWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"sidebar\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import { SafeAreaView, ScrollView, Pressable, Text, StyleSheet } from \"react-native\";\nimport { createNativeTheme } from \"nthgui/native\";\n\nexport function SidebarDrawer({\n  items,\n  activeId,\n  onSelect,\n}: {\n  items: { id: string; label: string }[];\n  activeId: string;\n  onSelect: (id: string) => void;\n}) {\n  const theme = createNativeTheme(\"dark\");\n  return (\n    <SafeAreaView style={[styles.rail, { backgroundColor: theme.colors.surface, borderRightColor: theme.colors.border }]}>\n      <ScrollView contentContainerStyle={styles.list}>\n        {items.map((item) => {\n          const active = item.id === activeId;\n          return (\n            <Pressable\n              key={item.id}\n              onPress={() => onSelect(item.id)}\n              style={[styles.item, active && { backgroundColor: theme.colors.interactive }]}\n            >\n              <Text style={[styles.lbl, { color: active ? theme.colors.interactiveForeground : theme.colors.foregroundSecondary }]}>\n                {item.label}\n              </Text>\n            </Pressable>\n          );\n        })}\n      </ScrollView>\n    </SafeAreaView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  rail: { width: 260, borderRightWidth: StyleSheet.hairlineWidth, flex: 1 },\n  list: { padding: 12, gap: 4 },\n  item: { minHeight: 42, borderRadius: 10, paddingHorizontal: 12, justifyContent: \"center\" },\n  lbl: { fontFamily: \"JetBrainsMono-Regular\", fontSize: 12 },\n});",
