    "category": "Navigation & Layout",
    "description": "Sticky On-Page Table of Contents with Signal Red active rail indicator, nested heading indentation, and smooth section jumping.",
    "webFile": "/**\n * Nothing UI — Table of Contents (copy-in template via `npx nthgui add table-of-contents`)\n * Customize styling or compose directly on top of the single `nthgui` package.\n */\nimport * as React from \"react\";\nimport { cn } from \"@/lib/utils\";\nimport * as NthgUI from \"nthgui\";\n\nexport interface TableOfContentsWrapperProps extends React.HTMLAttributes<HTMLDivElement> {\n  children?: React.ReactNode;\n}\n\nexport function TableOfContentsContainer({ className, children, ...props }: TableOfContentsWrapperProps) {\n  return (\n    <div\n      data-nthgui-component=\"table-of-contents\"\n      className={cn(\n        \"rounded-2xl border border-[var(--nt-line)] bg-[var(--nt-surface)] p-4 text-[var(--nt-primary)]\",\n        className,\n      )}\n      {...props}\n    >\n      {children}\n    </div>\n  );\n}\n\nexport { NthgUI };\n",
    "nativeFile": "import { View, Pressable, Text, StyleSheet } from \"react-native\";\nimport { createNativeTheme } from \"nthgui/native\";\n\nexport function TableOfContents({\n  sections,\n  activeId,\n  onJump,\n}: {\n  sections: { id: string; label: string }[];\n  activeId: string;\n  onJump: (id: string) => void;\n}) {\n  const theme = createNativeTheme(\"dark\");\n  return (\n    <View style={[styles.wrap, { borderLeftColor: theme.colors.border }]}>\n      {sections.map((sec) => {\n        const active = sec.id === activeId;\n        return (\n          <Pressable key={sec.id} onPress={() => onJump(sec.id)} style={[styles.row, active && { borderLeftColor: theme.colors.signal, borderLeftWidth: 2 }]}>\n            <Text style={[styles.lbl, { color: active ? theme.colors.foreground : theme.colors.foregroundMuted }]}>{sec.label}</Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  wrap: { borderLeftWidth: 1, gap: 2 },\n  row: { paddingLeft: 12, minHeight: 34, justifyContent: \"center\", marginLeft: -1 },\n  lbl: { fontFamily: \"JetBrainsMono-Regular\", fontSize: 12 },\n});",
